  const box = (x0, x1, y0, y1, z0, z1, o) => S.xf(S.box(x1 - x0, y1 - y0, z1 - z0, o), { at: [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2] });
